export class SystemMessage extends Schema.Class("LLM.SystemMessage")({
    id: Schema.optional(Schema.String),
    role: Schema.Literal("system"),
    content: Schema.Array(Schema.Union([TextPart, EffortPart]).pipe(Schema.toTaggedUnion("type"))),
}) {
}
export class UserMessage extends Schema.Class("LLM.UserMessage")({
    id: Schema.optional(Schema.String),
    role: Schema.Literal("user"),
    content: Schema.Array(Schema.Union([TextPart, MediaPart]).pipe(Schema.toTaggedUnion("type"))),
    providerMetadata: Schema.optional(ProviderMetadata),
}) {
}
export class AssistantMessage extends Schema.Class("LLM.AssistantMessage")({
    id: Schema.optional(Schema.String),
    role: Schema.Literal("assistant"),
    content: Schema.Array(Schema.Union([TextPart, ReasoningPart, ToolCallPart, ToolResultPart, MediaPart, CompactionPart]).pipe(Schema.toTaggedUnion("type"))),
    providerMetadata: Schema.optional(ProviderMetadata),
}) {
}
export class ToolMessage extends Schema.Class("LLM.ToolMessage")({
    id: Schema.optional(Schema.String),
    role: Schema.Literal("tool"),
    content: Schema.Array(ToolResultPart),
}) {
}
